from src.workflow import Store, Archive, Workspace

class Env:
    def __init__(self):
        self.store = Store({'a': 'old', 'b': 'bee'})
        self.archive = Archive()
        self.events = []
        self.jobs = []
        self.next = 0
    def schedule(self, callback, delay):
        self.next += 1
        handle = self.next
        self.jobs.append([handle, callback, delay, True])
        return handle
    def cancel(self, handle):
        for job in self.jobs:
            if job[0] == handle:
                job[3] = False
    def run(self):
        for _, callback, _, active in list(self.jobs):
            if active:
                callback()
    def write(self, key, text): return self.store.write(key, text)
    def capture(self, value): return self.archive.capture(value)
    def output(self, name, value): self.events.append((name, value))

env = Env(); desk = Workspace(env)
desk.open('a'); desk.edit('one'); desk.edit('two')
assert env.store.read('a') == 'old'
env.run(); assert env.store.read('a') == 'two'
desk.edit('three'); desk.close(); assert env.store.read('a') == 'three'
assert not [value for name, value in env.events if name == 'status' and value['text'] == 'three']
desk.open('a'); desk.edit('four'); receipt = desk.submit()
assert receipt == {'id': 'a', 'text': 'four'} and env.store.read('a') == 'four'
desk.edit('five'); env.run(); assert env.store.read('a') == 'five'
print('workflow checks passed')
